solution:
#include <cmath>

double prob_between(double mu, double sigma, double a, double b) {
    if (a > b) return 0.0;
    auto cdf = [&](double x) { return 0.5 * std::erfc(-(x - mu) / (sigma * std::sqrt(2.0))); };
    return cdf(b) - cdf(a);
}

